style.css:
@-moz-document url-prefix("https://www.roblox.com"), url-prefix("https://www.web.roblox.com") {
/* navbar */
#header {
background-color: #fed3dc;
  border-color: #fed3dc;
}


  /* profile sections */
.dark-theme .section-content {
    background-color: transparent !important; 
}
    .light-theme .section-content {
    background: transparent !important;
}
    
    /* pfps */
    .avatar-card-image, 
    .profile-avatar-left {
        background-color: #fce1e500 !important;
}

  .slide-switcher.games {
    background:transparent !important;
}

  /* Profile groups */
  .slide-switcher .slide-item-container .slide-item-container-left {
    background-color: #fed3dc !important;
}
  .slide-switcher .slide-item-container .slide-item-container-right {
    background-color: #fed3dc !important;
}

  /* Profile collections */
.dark-theme .layer {
  background-color: #adbcdb00 !important;
}
    .light-theme .layer {
    background-color: #adbcdb00 !important;
}

  /* Profile item scroll through  */
  .profile-accoutrements-page {
    border: 1px solid #fed3dc !important;
}

  .page-active {
    background-color: #fed3dc !important;
}

  /* Join event button */
  .btn-growth-xs {
    background-color: #fed3dc8f !important;
}
  .btn-growth-xs:hover,
  .btn-growth-xs:focus {
    background-color: #691414 !important;
}

  /* Chat */
  .chat-container .chat-main .chat-header {
    background-color: #fed3dc8f !important;
}

  /* Avatar editor background */
  .avatar-back {
    background-image: url("https://i.imgur.com/qFmcbT0.png") !important;
}
    
    /* avatar editor navigation area */
    .rbx-tab .rbx-tab-heading {
    background-color: #fed3dc8f !important;
}
    .dark-theme .rbx-tabs-horizontal .rbx-tab .rbx-tab-heading:hover {
    color: #fed3dc8f;
    background-color: #fed3dc8f;
    box-shadow: inset 0 -4px #7f2622;
}
    .tab-horizontal-submenu {
      box-shadow: 0 1px 3px #fed3dc8f !important;
}
    
    .light-theme .rbx-tabs-horizontal .rbx-tab .rbx-tab-heading:hover {
    color: #fed3dc8f;
    background-color: #fed3dc8f;
    box-shadow: inset 0 -4px #fed3dc8f;
}

.light-theme .section-content.remove-panel {
    background-color: transparent !important;
}
    
    /* groups */
    .groups-list-sidebar {
    background-color: #fed3dc8f;
    border-left: 1px solid #fed3dc;
}
    .group-section-content {
    background-color: #fed3dc;
}
    
    .dark-theme .input-field {
        color: #ffffff !important;
}
    
    
    /* group wall */
    .group-details .group-wall .comment {
    background-color: #9e1918;
}
        
  /* Friend list */
  .avatar-card-container {
    background-color: #9e1918 !important;
}
    .dark-theme .avatar-card-btns {
    background:transparent !important;
}

  /* Left column (sidebar) */
  .rbx-left-col {
    background-color: #fed3dc8f !important;
}
    
    
    /* inventory */
    .light-theme .rbx-tabs-vertical .category-tabs .menu-vertical {
    background-color: #9e1918;
}


 /* avatar item images */
  .light-theme .item-card-container .item-card-thumb-container {
    background-color: #ff9f9f42 !important;
    border-radius: 8px !important;
    overflow: hidden !important;
    position: relative !important;
  }

    




/* color changing play button */
.light-theme .btn-common-play-game-lg {
  animation: pastelPinkFlow 6s infinite alternate;
  transition: background-color 1s ease-in-out, box-shadow 1s ease-in-out, color 0.8s ease-in-out;
  color: #fffafc !important;
  text-shadow: 0 0 6px #ffe4ec, 0 0 12px #ffc0cb;
  border-radius: 8px !important;
  border: none !important;
  box-shadow: 0 0 12px #ffd1dc, 0 0 24px #ffc0cb;
}

@keyframes pastelPinkFlow {
  0%   { background-color: #ffe4ec; box-shadow: 0 0 10px #ffe4ec; }
    25%  { background-color: #ffd1dc; box-shadow: 0 0 12px #ffd1dc; }
    50%  { background-color: #ffc0cb; box-shadow: 0 0 14px #ffc0cb; }
    75%  { background-color: #ffb6c1; box-shadow: 0 0 16px #ffb6c1; }
    100% { background-color: #f9a6b0; box-shadow: 0 0 18px #f9a6b0; }
}





/* catalog */
#catalog-react-container .catalog-revamp .catalog-item-container .item-card-thumb-container {
    background-color: transparent !important;
}

.light-theme .text-robux-tile {
    color: #000000;
}

/* settings */
.light-theme .dropdown-menu {
    background-color: #ffebef;
}





  /* join someone button */
.light-theme .btn-control-xs {
    background-color: #fed3dc;
}

  /* join someone button on their profile */
.web-blox-css-tss-lo77dr-Button-contained {
    background-color: #ffb5c5;
}
.web-blox-css-tss-lo77dr-Button-contained:hover {
    background-color: #ffd8e0;
}






/* messages - read and unread colors */
.light-theme .messages .messageDivider.unread {
    background-color: #d3c0c4;
}
.light-theme .messages .messageDivider.read {
    background-color: #ffecf0;
}



/* accept ignore friend requests */
.light-theme .avatar-card-container {
    background-color: #ffffff;
}
.light-theme .avatar-card-btns {
    background-color: #ffffff;
}
.light-theme .avatar-card-btns .accept-friend {
    background-color: #9b7b82;
    border-color: #9b7b82;
}


/*Background*/
body, .content
{
     background: transparent !important;
}
.light-theme, .dark-theme, .nav-content
{
     width: 100% !important;
     height: 100% !important;
     background-attachment: fixed !important;
       background-size: cover !important; /* stretch width and height */
  background-repeat: no-repeat;
  background-position: center;
  background-image: url("data:image/png;base64,") !important;
  }
}
